163: function requirement(task, requirement, host) {
164:   return task.evidence.some(e => e.claims?.includes(requirement.claim)
165:     && e.task_binding === taskBinding(task)
166:     && (!requirement.skill || e.skill === requirement.skill)
167:     && (!requirement.kind || e.kind === requirement.kind)
168:     && (requirement.kind !== 'review' || (e.kind === 'review' && e.independent === true && host.reviewBinding && e.review_basis === host.reviewBinding))
169:     && evidenceValidity(e, host).status === 'valid');
170: }
