172: function stepEvidence(task, stage, host) {
173:   const step = task.steps[stage.id];
174:   if (!evidenceFor(task, step.evidence_ids, host)) return false;
175:   const evidence = step.evidence_ids.map(id => task.evidence.find(e => e.id === id));
176:   if (!evidence.some(e => e.skill === stage.skill && e.request_binding === digest(host.requests[stage.id]) && e.claims?.includes(`stage:${stage.id}`))) return false;
177:   if (stage.skill === 'safe-code-review' && !evidence.some(e => e.kind === 'review' && e.independent === true
178:       && e.review_basis && e.review_basis === host.reviewBinding)) return false;
179:   if (stage.skill === 'bug-root-cause-analysis' && !evidence.some(e => e.signal_ids?.length
180:       && e.signal_ids.every(id => task.evidence.some(signal => signal.id === id && signal.kind === 'signal' && signal.task_binding === taskBinding(task)
181:         && evidenceValidity(signal, host).status === 'valid')))) return false;
182:   return true;
183: }
