185: /** Recompute a decision every time. No imported context field grants execution authority. */
186: export function nextAction(task, host) {
187:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
188:   const workflow = definition(task, host.registry, host.inventory);
189:   assert(Object.keys(task.steps).length === workflow.stages.length && workflow.stages.every(s => task.steps[s.id]), 'Task stages differ from Registry');
190:   if (!host.scopeReviewed) return { action: 'evidence_insufficient', reason: 'risk_and_dependency_scope_not_reviewed' };
191:   if (workflow.stages.length > 1 && !host.continuationAuthorized) return { action: 'permission_blocked', reason: 'continuous_workflow_not_authorized' };
192:   if (host.openDecisions?.length) return { action: 'decision_required', skill: 'requirements-clarification', reason: host.openDecisions.join(', ') };
193:   if (host.activeStops?.length) return { action: 'blocked', reason: host.activeStops.join(', ') };
194:   const recovery = recoveryBinding(task, host);
195:   const recoveryCheck = recovery && host.recoveryChecks?.get(recovery);
196:   if (recovery && (!recoveryCheck?.source || recoveryCheck.reconciled !== true)) return { action: 'blocked', reason: 'recovered_execution_state_needs_reconciliation' };
197:   // Unknown effects cannot disappear when an optional predicate or prerequisite changes.
198:   const inflight = workflow.stages.find(stage => ['running', 'interrupted'].includes(task.steps[stage.id].status));
199:   if (inflight) return { stage: inflight.id, skill: inflight.skill, action: 'blocked', reason: 'inflight_operation_needs_reconciliation' };
200:   const uncertain = workflow.stages.find(stage => task.steps[stage.id].effect_state === 'uncertain');
201:   if (uncertain) return { stage: uncertain.id, skill: uncertain.skill, action: 'validation_failed', reason: 'failed_operation_needs_reconciliation' };
202:   const completed = new Set();
203:   for (const stage of workflow.stages) {
204:     const step = task.steps[stage.id];
205:     if (stage.prerequisites.some(id => !completed.has(id))) continue;
206:     if (step.request_binding && step.request_binding !== digest(host.requests?.[stage.id])) {
207:       return { stage: stage.id, skill: stage.skill, action: 'evidence_insufficient', reason: 'operation_scope_changed' };
208:     }
209:     const applies = condition(task, stage.condition, host);
210:     const decision = { stage: stage.id, skill: stage.skill };
211:     const stop = [...(workflow.stop_conditions ?? []), ...stage.stop_conditions]
212:       .find(name => condition(task, name, host) === true);
213:     if (stop) return { ...decision, action: 'blocked', reason: `stop_condition:${stop}` };
214:     if (applies === undefined) return { ...decision, action: 'evidence_insufficient', reason: `condition_unknown:${stage.condition}` };
215:     if (!applies) {
216:       if (!stage.optional) return { ...decision, action: 'evidence_insufficient', reason: `required_condition_false:${stage.condition}` };
217:       if (step.status !== 'skipped' || step.condition_binding !== digest(host.conditions[stage.condition])) return { ...decision, action: 'skip', reason: `not_applicable:${stage.condition}` };
218:       completed.add(stage.id); continue;
219:     }
220:     if (stage.type === 'gate') {
221:       const children = workflow.stages.filter(s => s.approval_gate === stage.id);
222:       if (!children.length) return { ...decision, action: 'permission_blocked', reason: 'gate_has_no_consumer' };
223:       for (const child of children) {
224:         const denied = permission(child.skill, child, task, host);
225:         if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
226:       }
227:       // Always re-evaluate gates against host grants, never reuse persisted approval.
228:       if (step.status !== 'completed') return { ...decision, action: 'approve', reason: 'existing_scoped_host_authorization' };
229:       completed.add(stage.id); continue;
230:     }

231:     const denied = permission(stage.skill, stage, task, host);
232:     if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
233:     if (['completed', 'reused'].includes(step.status) && stepEvidence(task, stage, host)) {
234:       completed.add(stage.id); continue;
235:     }
236:     const failure = step.status === 'validation_failed';
237:     if (failure) return { ...decision, action: 'validation_failed', reason: step.reason || 'explicit_retry_required' };
238:     // Risk checks are additive obligations referencing existing Skills, not new workflows.
239:     if (writes(stage, host)) {
240:       const gap = (host.risks ?? []).flatMap(r => host.registry.coordination?.risk_requirements?.[r]?.before_write ?? [{ claim: `unclassified-risk:${r}` }])
241:         .find(r => !requirement(task, r, host));
242:       if (gap) return { ...decision, action: 'risk_check', requirement: gap, reason: 'risk_requires_additional_evidence' };
243:     }
244:     const candidate = host.reuse?.[stage.id];
245:     if (candidate) {
246:       const provisional = copy(task); provisional.steps[stage.id].evidence_ids = candidate;
247:       if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: candidate, reason: 'valid_existing_result' };
248:     }
249:     if (writes(stage, host) && ['completed', 'reused'].includes(step.status)) {
250:       return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
251:     }
252:     return { ...decision, action: 'execute', reason: ['completed', 'reused'].includes(step.status) ? 'prior_evidence_stale_or_unknown' : 'applicable_stage', mode: host.execution === 'same_agent' ? 'same_agent' : 'manual_handoff' };
253:   }
254:   if (completed.size !== workflow.stages.length) return { action: 'evidence_insufficient', reason: 'unresolved_dependencies' };
255:   const obligations = [
256:     ...task.acceptance.map(id => ({ claim: `acceptance:${id}` })),
257:     ...([...completed].some(id => {
258:       const stage = workflow.stages.find(s => s.id === id);
259:       return task.steps[id].status !== 'skipped'
260:         && ['feature-implementation', 'safe-fix-implementation', 'safe-test-implementation'].includes(stage.skill);
261:     }) ? [{ claim: 'behavior-validation', kind: 'test' }] : []),
262:     ...(host.deliveryRequirements ?? []),
263:     ...(host.risks ?? []).flatMap(r => {
264:       const rules = host.registry.coordination?.risk_requirements?.[r];
265:       return rules ? [...rules.before_write, ...rules.before_delivery] : [{ claim: `unclassified-risk:${r}` }];
266:     }),
267:   ];
268:   const missing = obligations.filter(r => !requirement(task, r, host));
269:   if (task.unresolved.length || missing.length) return { action: 'evidence_insufficient', reason: 'delivery_not_proven', missing };
270:   return { action: 'complete', reason: 'applicable_stages_and_acceptance_proven', release_authorized: false };
271: }
