278: export function advance(task, host) {
279:   const action = nextAction(task, host);
280:   if (['skip', 'approve', 'reuse', 'execute'].includes(action.action)) {
281:     const step = task.steps[action.stage];
282:     step.status = { skip: 'skipped', approve: 'completed', reuse: 'reused', execute: 'running' }[action.action];
283:     step.reason = action.reason;
284:     if (['execute', 'reuse'].includes(action.action)) step.request_binding = digest(host.requests[action.stage]);
285:     if (action.action === 'execute') {
286:       step.attempts++;
287:       step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'uncertain' : 'none';
288:     }
289:     if (action.action === 'skip') {
290:       const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === action.stage);
291:       step.condition_binding = digest(host.conditions[stage.condition]);
292:     }
293:     if (action.evidence_ids) step.evidence_ids = action.evidence_ids;
294:     event(task, action.stage, step.status, action.reason);
295:   }
296:   task.next_actions = [action];
297:   return action;
298: }
