300: export function finishStep(task, stageId, evidenceIds, host, failureReason = null) {
301:   const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === stageId);
302:   const step = task.steps[stageId];
303:   assert(stage && step?.status === 'running', 'Only a running stage may finish');
304:   assert(step.request_binding === digest(host.requests[stageId]), 'Operation scope changed while running');
305:   const denied = permission(stage.skill, stage, task, host);
306:   assert(!denied, denied);
307:   if (failureReason) { step.status = 'validation_failed'; step.reason = failureReason; step.evidence_ids = [...evidenceIds]; }
308:   else {
309:     const provisional = copy(task); provisional.steps[stageId].evidence_ids = evidenceIds;
310:     assert(stepEvidence(provisional, stage, host), 'Completion requires valid, scoped evidence and independent review');
311:     step.evidence_ids = [...evidenceIds]; step.status = 'completed'; step.effect_state = step.effect_state === 'none' ? 'none' : 'known';
312:   }
313:   event(task, stageId, step.status, failureReason || 'observed_completion');
314: }
