316: /** Reopening is an explicit host decision; only descendants are reopened.
317:  * Evidence is retained, so still-valid independent checks can be reused.
318:  */
319: export function reopen(task, stageId, host, { reason, source, safeToRetry = false } = {}) {
320:   assert(reason && source, 'Reopen requires a sourced reason');
321:   const workflow = definition(task, host.registry, host.inventory);
322:   assert(task.steps[stageId], 'Unknown stage');
323:   const affected = new Set([stageId]);
324:   let changed = true;
325:   while (changed) { changed = false; for (const stage of workflow.stages) {
326:     if (!affected.has(stage.id) && stage.prerequisites.some(id => affected.has(id))) { affected.add(stage.id); changed = true; }
327:   } }
328:   for (const id of affected) {
329:     const stage = workflow.stages.find(s => s.id === id);
330:     if (['running', 'interrupted'].includes(task.steps[id].status)
331:         || task.steps[id].effect_state === 'uncertain'
332:         || ((writes(stage, host) || task.steps[id].effect_state === 'known') && ['completed', 'reused', 'validation_failed'].includes(task.steps[id].status))) {
333:       assert(safeToRetry && host.reconciled?.has(reconciliationBinding(task, id, host)), 'Unknown side effects must be reconciled before retry');
334:     }
335:   }
336:   for (const id of affected) { task.steps[id].status = 'pending'; task.steps[id].effect_state = 'reconciled'; event(task, id, 'pending', `${reason} (${source})`); }
337: }
